import type {
  InferContractRouterInputs,
  InferContractRouterOutputs,
} from "@orpc/contract";
import { z } from "zod";
import { createContractProcedureBuilder } from "../errors";

// Pagination constants
const DEFAULT_PAGE = 1;
const DEFAULT_PAGE_SIZE = 20;
const MAX_PAGE_SIZE = 100;
const MIN_PAGE = 1;

const USER_ROLES = [
  "STUDENT",
  "COUNSELOR",
  "UNIVERSITY_ADMIN",
  "ADMIN",
] as const;
export const UserRoleSchema = z.enum(USER_ROLES);
export type UserRole = (typeof USER_ROLES)[number];

// Common pagination schemas
const paginationInputSchema = z
  .object({
    page: z.number().int().min(MIN_PAGE).default(DEFAULT_PAGE).optional(),
    pageSize: z
      .number()
      .int()
      .min(1)
      .max(MAX_PAGE_SIZE)
      .default(DEFAULT_PAGE_SIZE)
      .optional(),
  })
  .strict();

const paginationOutputSchema = z
  .object({
    total: z.number().int().nonnegative(),
    page: z.number().int().min(MIN_PAGE),
    pageSize: z.number().int().min(1).max(MAX_PAGE_SIZE),
    totalPages: z.number().int().nonnegative(),
  })
  .strict();

// User schemas
const _userRoleSchema = UserRoleSchema;

const userListItemSchema = z
  .object({
    id: z.string(),
    firstName: z.string().nullable(),
    lastName: z.string().nullable(),
    name: z.string(),
    email: z.string().nullable(),
    emailVerified: z.boolean(),
    phoneNumber: z.string().nullable(),
    phoneNumberVerified: z.boolean(),
    role: _userRoleSchema,
    banned: z.boolean().nullable(),
    createdAt: z.string(), // ISO date string
    updatedAt: z.string(), // ISO date string
  })
  .strict();

const userDetailsSchema = z
  .object({
    id: z.string(),
    name: z.string(),
    firstName: z.string().nullable(),
    lastName: z.string().nullable(),
    gender: z.string().nullable(),
    country: z.string().nullable(),
    email: z.string().nullable(),
    emailVerified: z.boolean(),
    phoneNumber: z.string().nullable(),
    phoneNumberVerified: z.boolean(),
    image: z.string().nullable(),
    role: _userRoleSchema,
    banned: z.boolean().nullable(),
    banReason: z.string().nullable(),
    banExpires: z.string().nullable(), // ISO date string
    createdAt: z.string(),
    updatedAt: z.string(),
    sessionCount: z.number().int().nonnegative(),
    accountCount: z.number().int().nonnegative(),
  })
  .strict();

const listUsersInputSchema = paginationInputSchema.extend({
  search: z.string().min(1).optional(),
  role: _userRoleSchema.optional(),
  emailVerified: z.boolean().optional(),
  phoneNumberVerified: z.boolean().optional(),
  banned: z.boolean().optional(),
  sortBy: z
    .enum(["firstName", "lastName", "email", "role", "createdAt", "updatedAt"])
    .default("createdAt")
    .optional(),
  sortOrder: z.enum(["asc", "desc"]).default("desc").optional(),
});

const listUsersOutputSchema = z
  .object({
    items: z.array(userListItemSchema),
    pagination: paginationOutputSchema,
  })
  .strict();

const updateUserInputSchema = z
  .object({
    userId: z.string().min(1),
    name: z.string().min(1),
    firstName: z.string().min(1).optional(),
    lastName: z.string().min(1).optional(),
    gender: z.string().min(1).optional(),
    country: z.string().min(1).optional(),
  })
  .strict();

// Contract definition
const contractProcedure = createContractProcedureBuilder();

export const usersContract = {
  list: contractProcedure
    .input(listUsersInputSchema)
    .output(listUsersOutputSchema),
  get: contractProcedure
    .input(
      z.object({
        userId: z.string().min(1),
      }),
    )
    .output(userDetailsSchema),
  update: contractProcedure
    .input(updateUserInputSchema)
    .output(userDetailsSchema),
};

export type UsersContract = typeof usersContract;
export type UsersContractInputs = InferContractRouterInputs<UsersContract>;
export type UsersContractOutputs = InferContractRouterOutputs<UsersContract>;

// Type exports for easier usage
export type ListUsersInput = UsersContractInputs["list"];
export type ListUsersOutput = UsersContractOutputs["list"];
export type GetUserInput = UsersContractInputs["get"];
export type GetUserOutput = UsersContractOutputs["get"];
export type UpdateUserInput = UsersContractInputs["update"];
export type UpdateUserOutput = UsersContractOutputs["update"];
